test("JSON and YAML headers become a short header plus one hidden, lossless metadata appendix", () => {
	const yaml = legacy("yaml").replace("summary: Explain the stable behavior.", "summary: \"Explain #source without a comment.\""), json = `---\n${JSON.stringify({
		id: "json",
		title: "JSON",
		summary: "JSON #source document.",
		type: "mechanism",
		status: "current",
		locale: "en",
		sources: [{
			id: "code",
			repoId: "root",
			path: "src/session.ts"
		}],
		watchScopes: [{
			repoId: "root",
			path: "src/session.ts"
		}],
		customField: "private_marker_tail"
	})}\n---\n# JSON\n\nExplanation.\n`;
	for (const [id, markdown] of [["yaml", yaml], ["json", json]]) {
		const relative = `docs/repo-wiki/${id}.md`, before = parseDocument(markdown, relative), formatted = formatWikiDocument(markdown, relative), after = parseDocument(formatted, relative);
		assert.equal(isStructuredWikiDocument(formatted), true);
		assert.equal(formatWikiDocument(formatted, relative), formatted);
		assert.deepEqual(after.body, before.body);
		for (const key of [
			"id",
			"title",
			"summary",
			"type",
			"status",
			"locale",
			"sources",
			"watchScopes",
			"sections",
			"diagrams",
			"relations"
		]) assert.deepEqual(after[key], before[key], key);
		assert.doesNotMatch(formatted.split("---\n")[1], /sources:|customField|watchScopes/);
		assert.match(formatted, /<!-- lumine-wiki-metadata:v1/);
		assert.doesNotMatch(after.body, /private_marker_tail|lumine-wiki-metadata/);
		assert.equal(searchKnowledge([after], "private_marker_tail", 6, 12e3).cards.length, 0);
	}
	assert.throws(() => parseDocument(formatWikiDocument(yaml, "docs/repo-wiki/yaml.md").replace("\n-->\n", "\n-- invalid>\n"), "docs/repo-wiki/yaml.md"), /TRAILING_METADATA_INVALID/);
});
test("legacy YAML comments stop conversion instead of disappearing, including nested and inline comments", () => {
	const examples = [
		legacy("commented").replace("id: commented", "# reviewer note\nid: commented"),
		legacy("commented").replace("title: commented mechanism", "title: commented mechanism # keep this wording"),
		legacy("commented").replace("  - id: code", "  # source chosen by the reviewer\n  - id: code")
	];
	for (const markdown of examples) assert.throws(() => formatWikiDocument(markdown, "docs/repo-wiki/commented.md"), /DOCUMENT_FRONTMATTER_COMMENTS_PRESENT/);
	const data = fixture();
	try {
		const { relative } = data.create("commented");
		const withComment = legacy("commented").replace("title: commented mechanism", "title: commented mechanism # human note");
		writeFileSync(path.join(data.root, relative), withComment);
		const oldBaseline = baselineFor(data.root, "commented");
		const planned = planWikiDocumentFormat(data.root).find((item) => item.id === "commented");
		assert.equal(planned?.status, "blocked");
		assert.equal(planned?.reason, "DOCUMENT_FRONTMATTER_COMMENTS_PRESENT");
		assert.equal(migrateWikiDocumentFormat(data.root, "commented").status, "blocked");
		assert.equal(readFileSync(path.join(data.root, relative), "utf8"), withComment);
		assert.deepEqual(baselineFor(data.root, "commented"), oldBaseline);
	} finally {
		data.close();
	}
});
