test("format migration keeps human edits, baseline, source observation and review evidence without advancing their dates", () => {
	const data = fixture();
	try {
		const { markdown, relative } = data.create("session");
		const old = showKnowledge(data.root, "session");
		const review = {
			documentId: "session",
			revision: old.revision,
			sourceFingerprint: old.sourceObservation.sourceFingerprint,
			reviewedAt: "2026-01-01T00:00:00.000Z",
			reviewer: {
				kind: "agent",
				role: "author"
			},
			outcome: "reviewed",
			scope: ["Normal flow"],
			findings: [],
			limitations: ["Deployment not checked"]
		};
		recordSemanticReview(data.root, review);
		scanWiki(data.root);
		const previousBaseline = baselineFor(data.root, "session");
		const previousObservation = JSON.parse(readFileSync(path.join(data.root, statePath("observations", "session")), "utf8"));
		const current = markdown.replace("Human limitation.", "Human limitation, edited after generation.");
		writeFileSync(path.join(data.root, relative), current);
		const before = parseDocument(current, relative), plan = planWikiDocumentFormat(data.root);
		assert.equal(plan.find((item) => item.id === "session")?.status, "eligible");
		const migrated = migrateWikiDocumentFormat(data.root, "session");
		assert.equal(migrated.status, "converted");
		const after = showKnowledge(data.root, "session");
		assert.equal(after.body, before.body);
		assert.deepEqual(after.sections, before.sections);
		assert.deepEqual(after.diagrams, before.diagrams);
		assert.deepEqual(after.sources, before.sources);
		assert.equal(after.semanticReview.status, "outdated", "the human body edit still invalidates the earlier review");
		const baseline = baselineFor(data.root, "session");
		assert.equal(baseline.updatedAt, previousBaseline.updatedAt);
		assert.equal(baseline.sources.scopeFingerprints["root:src/session.ts"], previousBaseline.sources.scopeFingerprints["root:src/session.ts"]);
		assert.equal(baseline.appliedRevision, hash(formatWikiDocument(markdown, relative)));
		const observation = JSON.parse(readFileSync(path.join(data.root, statePath("observations", "session")), "utf8"));
		assert.equal(observation.checkedAt, previousObservation.checkedAt);
		assert.equal(observation.revision, previousObservation.revision, "an observation tied to older text is not silently renewed");
		const savedReview = JSON.parse(readFileSync(path.join(data.root, statePath("reviews", "session")), "utf8"));
		assert.equal(savedReview.reviewedAt, review.reviewedAt);
		assert.equal(savedReview.revision, review.revision);
		const packet = prepareUpdate(data.root, ["session"]);
		const candidate = markdown.replace("Normal flow.", "Normal flow with a new recovery detail.");
		const applied = applyUpdate(data.root, packet.id, [{
			id: "session",
			markdown: candidate
		}]);
		assert.equal(applied.status, "applied", JSON.stringify(applied));
		assert.match(showKnowledge(data.root, "session").body, /Human limitation, edited after generation/);
		assert.match(showKnowledge(data.root, "session").body, /new recovery detail/);
	} finally {
		data.close();
	}
});
test("an unresolved packet blocks only its unapplied units", () => {
	const data = fixture();
	try {
		data.create("first");
		data.create("second");
		const packet = prepareUpdate(data.root, ["first", "second"]);
		assert.equal(applyUpdate(data.root, packet.id, [{
			id: "first",
			markdown: legacy("first")
		}]).status, "partial");
		const plan = planWikiDocumentFormat(data.root);
		assert.equal(plan.find((item) => item.id === "first")?.status, "eligible");
		assert.deepEqual(plan.find((item) => item.id === "second")?.status, "blocked");
		assert.equal(plan.find((item) => item.id === "second")?.reason, "UNRESOLVED_UPDATE_PACKET");
		assert.equal(migrateWikiDocumentFormat(data.root, "first").status, "converted");
		assert.equal(migrateWikiDocumentFormat(data.root, "second").status, "blocked");
		assert.equal(readFileSync(path.join(data.root, "docs/repo-wiki/second.md"), "utf8"), legacy("second"));
		recordUpdateDecision(data.root, packet.id, "second", "keep-current", "The stale candidate is retained for history; current text will be reviewed in a new packet.");
		assert.equal(planWikiDocumentFormat(data.root).find((item) => item.id === "second")?.status, "eligible");
		assert.equal(migrateWikiDocumentFormat(data.root, "second").status, "converted");
		assert.equal(JSON.parse(readFileSync(path.join(data.root, `.lumine/wiki-state/updates/${packet.id}/packet.json`), "utf8")).status, "partial");
	} finally {
		data.close();
	}
});
